assigned_control:
struct S{n:i64}
var target:S=S{n:1};var yes:bool=true;
fn main(){target=if yes{S{n:target.n+1}}else{S{n:9}};assert(target.n==2);target={var old:i64=target.n;S{n:old+1}};assert(target.n==3);print("assigned_control");}

block_argument:
struct S{n:i64}
recursive fn read(p:S)->i64{return p.n;}
fn main(){assert(read({var s:S=S{n:7};defer{s.n=9;}s})==7);print("block_argument");}

data:
struct S{n:i64}
struct H{s:S}
recursive fn make(n:i64)->S{return S{n:n};}
fn main(){var rows:H[]=[H{s:make(7)}];assert(rows[0].s.n==7);rows[0].s=make(9);assert(rows[0].s.n==9);print("data");}

refs:
struct S{link:i64&,n:i64}
recursive fn make(link:i64&,n:i64)->S{return S{link:link,n:n};}
recursive fn duplicate(p:S)->S{return p;}
fn main(){var values:i64[]=[7];var s:S=duplicate(make(values[0],9));assert(s.n==9);s.link++;assert(values[0]==8);assert(s.link .== &values[0]);print("refs");}

dynamic_base:
struct S{n:i64}
recursive fn make(n:i64)->S{var a:i64[]=[n];return S{n:a[0]};}
fn main(){var a:S=make(7);assert(a.n==7);{var live:i64[]=[9];var b:S=make(8);assert(b.n==8);assert(live[0]==9);}print("dynamic_base");}
